def sift_down(a, i, n):
    while True:
        small = i
        for c in (2 * i + 1, 2 * i + 2):
            if c < n and a[c] < a[small]:
                small = c
        if small == i:
            return
        a[i], a[small] = a[small], a[i]
        i = small

def build_heap(a):
    for i in range(len(a) // 2 - 1, -1, -1):
        sift_down(a, i, len(a))
    return a

print(build_heap([9, 4, 7, 1, 8, 2, 6]))

