class Node:
    def __init__(self, k):
        self.k, self.l, self.r = k, None, None

def insert(t, k):
    if t is None:
        return Node(k)
    if k < t.k:
        t.l = insert(t.l, k)
    else:
        t.r = insert(t.r, k)
    return t

def delete(t, k):
    if t is None:
        return None
    if k < t.k:
        t.l = delete(t.l, k)
    elif k > t.k:
        t.r = delete(t.r, k)
    else:
        if t.l is None:
            return t.r
        if t.r is None:
            return t.l
        s = t.r
        while s.l:
            s = s.l
        t.k = s.k
        t.r = delete(t.r, s.k)
    return t

def pre(t):
    return [] if t is None else [t.k] + pre(t.l) + pre(t.r)

root = None
for k in [50, 30, 70, 20, 40, 60, 80, 65]:
    root = insert(root, k)
root = delete(root, 50)
print(*pre(root))

def sort_count(a):
    if len(a) <= 1:
        return a, 0
    mid = len(a) // 2
    L, x = sort_count(a[:mid])
    R, y = sort_count(a[mid:])
    out, i, j, cross = [], 0, 0, 0
    while i < len(L) and j < len(R):
        if L[i] <= R[j]:
            out.append(L[i]); i += 1
        else:
            out.append(R[j]); j += 1
            cross += len(L) - i
    out += L[i:] + R[j:]
    return out, x + y + cross

